@app.websocket("/ws/telemetry")
async def device_telemetry_stream(
    websocket: WebSocket,
    current_user: User = Depends(get_current_user_ws),
    db: Session = Depends(get_db)
):
    await websocket.accept()
    active_subscriptions = set()
    try:
        while True:
            message = await websocket.receive_json()
            if message.get("type") == "subscribe":
                device_id = message.get("device_id")
                device = db.query(Device).filter(Device.id == device_id, Device.owner_id == current_user.id).first()
                if not device:
                    await websocket.send_json({"error": "Device not found or access denied", "device_id": device_id})
                    continue
                await telemetry_broker.subscribe(device_id, websocket)
                active_subscriptions.add(device_id)
                await websocket.send_json({"status": "subscribed", "device_id": device_id})
    except WebSocketDisconnect:
        for dev_id in active_subscriptions:
            telemetry_broker.unsubscribe(dev_id, websocket)
